        "name": "The Menopause Society (NAMS) - 2022 Hormone Therapy Position Statement",
        "url": "https://www.menopause.org/docs/default-source/professional/nams-2022-hormone-therapy-position-statement.pdf",
        "organization": "The Menopause Society",
        "year": 2022,
